function removeSession(n){const t=Swal.mixin({customClass:{confirmButton:"btn btn-success p-2",cancelButton:"btn btn-danger"},buttonsStyling:!1});t.fire({title:"Are you sure?",text:"You won't be able to revert this!",icon:"warning",showCancelButton:!0,confirmButtonText:"Yes, delete it!",cancelButtonText:"No, cancel!",reverseButtons:!0}).then(i=>{i.isConfirmed?$.ajax({type:"DELETE",url:n,success:function(n){$.unblockUI();n.success?(swal.fire("Deleted!",n.message,"success"),datatablez.ajax.reload()):swal.fire("Deleted!",n.message,"error")},beforeSend:function(){blockcallback()},error:function(){$.unblockUI();Swal.fire({icon:"error",title:"Oops...",text:"Something went wrong!",footer:"Check internet connectivity"})},complete:function(){$.unblockUI()}}):i.dismiss===Swal.DismissReason.cancel&&t.fire("Cancelled","PTA Fees Payment Record NOT Deleted","error")})}function viewPayment(n){function t(n){if($.unblockUI(),n.success){$("#employee1").val(n.data.applicationUser.fullname);$("#subject1").val(n.data.subject);$("#sender1").val(n.data.sender);$("#message1").val(n.data.message);$("#cash").val(n.data.cost);var t=new Date(n.data.createdDate).getHours();let i=t>=12?"pm":"am",r=n.data.createdDate.toLocaleString("YYYY-MM-dd").slice(0,19).replace("T"," ")+" "+i;$("#createdate1").val(r);$("#staticBackdrop").modal("show")}else $.unblockUI(),swal.fire("Ooop!","An error occured while generating the report","error")}function i(){$("#smsloader"+id).hide();$("#nosmsloader"+id).show();$.unblockUI();Swal.fire({icon:"error",title:"Oops...",text:"Something went wrong!",footer:"Check internet connectivity!"})}$.ajax({type:"POST",url:n,dataType:"json",success:t,error:i,beforeSend:function(){blockcallback()},complete:function(){$.unblockUI()}})}function blockcallback(){$.blockUI({message:'<div class="bs-spinner mt-4 mt-lg-0"><div class= "spinner-border text-success mr-2 mt-2" style="width: 10rem; height: 10rem;" role="status"><span class="sr-only">Loading...<\/span><\/div> ',fadeIn:800,overlayCSS:{backgroundColor:"#1b2024",opacity:.8,zIndex:1200,cursor:"wait"},css:{border:0,color:"#fff",zIndex:1201,padding:0,backgroundColor:"transparent"},onBlock:function(){}})}var font,clazz,datatablez;$(document).ready(function(){datatablez=$("#studentdata").DataTable({processing:!0,serverSide:!0,filter:!0,paging:!0,responsive:!0,ajax:{url:"/Home/PTAFeesPayemtData",type:"POST",datatype:"json"},columnDefs:[{targets:[0],visible:!0,searchable:!0}],columns:[{data:"id",render:function(n,t,i,r){return r.row+r.settings._iDisplayStart+1}},{data:null,render:function(n){return n.termregistration.studentsData.surName+" "+(n?.termregistration.studentsData.otherName||"")+" "+n.termregistration.studentsData.firstName}},{data:"termregistration.studentsData.studentRegNo",autoWidth:!0},{data:"ptaFee.fees",autoWidth:!0},{data:"amount",autoWidth:!0},{data:"balance",autoWidth:!0},{data:"termregistration.term",autoWidth:!0},{data:"termregistration.sessionYear.name",autoWidth:!0},{data:null,render:function(n){return n.termregistration.schoolclasses.name+" - "+(n.termregistration.subClasses.name||"")}},{data:null,render:function(n){if(n.createdDate.length>10)return n.createdDate.substring(0,10)}},{data:null,render:function(n){return`
                        <div class="d-flex justify-content-between">
                            <a class="btn btn-primary btn-sm" target="_blank" title="View Payment Invoice" href="/ultilities/Pta-Payment-Invoice?id=${n.id}"  style="cursor:pointer">
                                <i class="fa fa-print"></i>
                            </a>
                            &nbsp;
                            <a onclick=removeSession("/api/PTAFeesPaymentManager/${n.id}") title="Permanently Remove this Expenditure" class="btn btn-danger btn-sm" href="#" style="cursor:pointer">
                                <i class="fa fa-trash"></i>
                            </a>
                        </div>
                    `}}]})});